        normalized_path = "/".join(components)
        key_components = [unicodedata.normalize("NFC", part.casefold()) for part in components]
        key = "/".join(key_components)
        validated.append((normalized_path, key, key_components, kind))

        if kind == "file":
            file_count += 1
            total_file_size += size

    if file_count > 100:
        raise ValueError("too many files")
    if total_file_size > 1_000_000:
        raise ValueError("total file size exceeds limit")

    explicit = {}
    for _, key, _, kind in validated:
        if key in explicit:
            raise ValueError("duplicate or case-insensitive path collision")
        explicit[key] = kind

    file_keys = {key for _, key, _, kind in validated if kind == "file"}
    for _, _, key_components, _ in validated:
        for end in range(1, len(key_components)):
            if "/".join(key_components[:end]) in file_keys:
                raise ValueError("a file cannot be an ancestor of another entry")

    return [path for path, _, _, kind in validated if kind == "file"]

import unicodedata

_DEVICE_NAMES = {
    "con", "prn", "aux", "nul",
    *(f"com{i}" for i in range(1, 10)),
    *(f"lpt{i}" for i in range(1, 10)),
}


def plan(entries):
    if not isinstance(entries, list):
        raise ValueError("entries must be a list")

    validated = []
    file_count = 0
    total_file_size = 0

    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("each entry must be a dict")
        if "path" not in entry or "size" not in entry or "kind" not in entry:
            raise ValueError("entry is missing a required field")

        path = entry["path"]
        size = entry["size"]
        kind = entry["kind"]

        if not isinstance(path, str):
            raise ValueError("path must be a string")
        if type(size) is not int or size < 0:
            raise ValueError("size must be an exact nonnegative int")
        if type(kind) is not str or kind not in ("file", "dir"):
            raise ValueError("kind must be 'file' or 'dir'")
        if kind == "dir" and size != 0:
            raise ValueError("directory size must be zero")
        if "\x00" in path or any(unicodedata.category(ch) == "Cc" for ch in path):
            raise ValueError("path contains a control character")

        separated = unicodedata.normalize("NFC", path).replace("\\", "/")
        if separated.startswith("/"):
            raise ValueError("absolute paths are not allowed")

        has_trailing_slash = separated.endswith("/")
        if has_trailing_slash and kind == "file":
            raise ValueError("file path may not end in a slash")

        components = []
        for component in separated.split("/"):
            if component == "" or component == ".":
                continue
            if component == "..":
                raise ValueError("parent path components are not allowed")
            if ":" in component:
                raise ValueError("colon is not allowed in path components")
            if component.endswith((".", " ")):
                raise ValueError("path component may not end in a period or space")
            basename = component.split(".", 1)[0]
            if basename.casefold() in _DEVICE_NAMES:
                raise ValueError("Windows device path component is not allowed")
            components.append(component)

        if not components:
            raise ValueError("path must not normalize to empty")

        normalized_path = "/".join(components)
        key_components = tuple(
            unicodedata.normalize("NFC", component.casefold())
            for component in components
        )
        validated.append((kind, normalized_path, key_components))

        if kind == "file":
            file_count += 1
            total_file_size += size

    if file_count > 100:
        raise ValueError("too many files")
    if total_file_size > 1_000_000:
        raise ValueError("total file size exceeds limit")

    seen = {}
    for kind, normalized_path, key_components in validated:
        if key_components in seen:
            raise ValueError("duplicate or file/directory path collision")
        seen[key_components] = kind

    keys = list(seen)
    for key in keys:
        for end in range(1, len(key)):
            ancestor = key[:end]
            if seen.get(ancestor) == "file":
                raise ValueError("a file is an ancestor of another entry")

    return [
        normalized_path
        for kind, normalized_path, _ in validated
        if kind == "file"
    ]
